/* ---------- Classement automatique des recettes ---------- */
(function () {
  const VIA = /poulet|dinde|boeuf|bœuf|agneau|merguez|steak|veau|grisons|jambon|knacki|cuisse|ailes|kefta|côtelette|lardons/i, POI = /saumon|thon|crevette|cabillaud|moules|colin|poisson|surimi/i;
  RECIPES.forEach(r => {
    const t = r.ing.map(x => x[0]).join(' '), v = VIA.test(t), p = POI.test(t);
    r.main = p && !v ? 'poisson' : v ? 'viande' : 'vege';
    const add = k => { if (!r.tags.includes(k)) r.tags.push(k); };
    add(r.main); add(r.tags.includes('froid') ? 'froid' : 'chaud');
    if (r.k >= 700) add('copieux'); if (r.k <= 420) add('leger'); if (r.p >= 38 || r.p * 4 / r.k >= .24) add('proteine');
    if (r.min <= 15) add('rapide');
  });
})();
